-- =====================================================================
-- CPSU ETMS — ข้อมูลทดลองสำหรับฝั่งผู้จัดกิจกรรม (DEMO)
--
-- Generated file. Covers every situation an organizer meets: not yet open,
-- open, full, closed, paid with slips in every state, hybrid, online, today
-- (check-in), multi-day in progress, ended awaiting certificates, closed with
-- certificates/evaluations/SAR, a previous fiscal year, and the blacklist.
--
-- All dates are relative to "today" (Thai time), so it can be re-run any day.
-- Re-running replaces the previous demo rows only (ids 1001–1099 for users
-- and events, 900001–900007 for blacklist/notifications/logs); real data is untouched.
--
-- Apply AFTER schema.sql and seed.sql:
--   docker exec -i cpsu-etms-mysql mysql -uroot -p<password> cpsu_etms < database/demo_organizer.sql
--
-- Demo students log in with "Passw0rd!" (e.g. demo.student01@silpakorn.edu).
-- =====================================================================

USE cpsu_etms;
SET NAMES utf8mb4;
SET @t := DATE(UTC_TIMESTAMP() + INTERVAL 7 HOUR);

-- remove earlier demo rows (registrations, check-ins, certificates,
-- evaluations, SAR cascade from events/users)
DELETE FROM notifications     WHERE id BETWEEN 900001 AND 900004;
DELETE FROM activity_logs     WHERE id BETWEEN 900001 AND 900007;
DELETE FROM blacklist_entries WHERE id BETWEEN 900001 AND 900002;
DELETE FROM events            WHERE id BETWEEN 1001 AND 1099;
DELETE FROM users             WHERE id BETWEEN 1001 AND 1099;

-- ------------------------------------------------------------------ demo students

-- E1001 ยังไม่เปิดรับสมัคร (เร็ว ๆ นี้)

-- E1002 เปิดรับสมัคร ฟรี · ให้ยืมโน้ตบุ๊ก · ถามเรื่องอาหาร · มีข้อความถึงผู้เข้าร่วม

-- E1003 เต็มแล้ว

-- E1004 ปิดรับสมัครแล้ว รอวันจัด

-- E1005 มีค่าลงทะเบียน · สลิปครบทุกสถานะ

-- E1006 Hybrid (Onsite + Online) เปิดรับสมัคร

-- E1007 จัดวันนี้ (Onsite) · เช็คอินได้

-- E1008 จัดวันนี้ (Online) · ผู้เข้าร่วมเช็คอินเองผ่านลิงก์

-- E1009 หลายวัน กำลังจัดอยู่ (วันที่ 2 จาก 3)

-- E1010 จบแล้ว รอออกเกียรติบัตร · ยังไม่บันทึกงบจริง

-- E1011 ปิดกิจกรรมแล้ว · ออกเกียรติบัตร · มีผลประเมิน (รวมคำถามเพิ่มเติม) · มีโปสเตอร์สรุปข่าว · บันทึกงบจริงแล้ว

-- E1012 การแข่งขัน หลายวัน มีแบบทดสอบก่อนเข้าร่วม (pretest) เปิดรับสมัคร

-- E1013 ปีงบประมาณก่อน · ปิดกิจกรรมแล้ว แต่ยังไม่บันทึกงบจริงและยังไม่มีโปสเตอร์สรุปข่าว

-- ------------------------------------------------------------------ registrations


-- ------------------------------------------------------------------ evaluation questions (every event)

-- ------------------------------------------------------------------ evaluations + certificates



-- ------------------------------------------------------------------ SAR (recap poster) for E1011

-- ------------------------------------------------------------------ blacklist: 1 active, 1 restored
SELECT 900001, id, name, email, student_id, 'ลงทะเบียนแล้วไม่มาเข้าร่วมโดยไม่แจ้งล่วงหน้า 3 ครั้งในปีงบประมาณ', 2, TIMESTAMP((@t + INTERVAL -6 DAY), '09:00:00'), NULL FROM users WHERE id = 1030;
SELECT 900002, id, name, email, student_id, 'ใช้บัญชีผู้อื่นลงทะเบียนแทน', 2, TIMESTAMP((@t + INTERVAL -30 DAY), '10:00:00'), TIMESTAMP((@t + INTERVAL -10 DAY), '14:00:00') FROM users WHERE id = 1029;

-- ------------------------------------------------------------------ organizer notifications

-- ------------------------------------------------------------------ activity log

-- The demo students are made-up addresses: mark them verified, or signing in
-- as one would wait for an email code that can never arrive.
UPDATE users SET email_verified_at = UTC_TIMESTAMP()
WHERE email_verified_at IS NULL AND email LIKE 'demo.student__@silpakorn.edu';
