  (1001, 'สัมมนา AI ในอุตสาหกรรมซอฟต์แวร์ 2027', 'อัปเดตการนำ Generative AI มาใช้ในการพัฒนาซอฟต์แวร์ โดยวิทยากรจากภาคอุตสาหกรรม', 'อบรมเชิงบรรยาย', 'AI / Data', 'data:image/svg+xml;base64,', 2, 'ภาควิชาคอมพิวเตอร์', 'single', (@t + INTERVAL 25 DAY), NULL, NULL, NULL, '13.00–16.00 น.', (@t + INTERVAL 5 DAY), (@t + INTERVAL 20 DAY), 'onsite', 'ห้อง CS-301 อาคารวิทยาการคอมพิวเตอร์ คณะวิทยาศาสตร์', NULL, 80, NULL, NULL, 8000, NULL, NULL, NULL, NULL, 0, NULL, NULL, 'open', 0, 0, NULL, NULL, NULL, 'ผศ.ดร. ปิยะ จันทรัศมี', 'หัวหน้าภาควิชาคอมพิวเตอร์', TIMESTAMP((@t + INTERVAL -1 DAY), '10:00:00'));
